// File: StriveStakingFinal.sol


pragma solidity 0.8.19;

/*
 * Final Strive Staking Contract
 * -----------------------------
 * Key Features:
 *  - "Staking Open Time": No one can stake before this timestamp.
 *  - "Reward Claim Delay": 8 hours after stakingOpenTime,
 *    users can call getReward() to claim their accrued rewards.
 *  - Simple linear rewards based on rewardRate (tokens/sec).
 *  - Must be funded with STRIVE tokens for actual payouts.
 *
 * Usage Steps:
 *  1. Deploy the contract before the official open time, specifying:
 *      - striveToken = 0x7897fC1eFD0027d2A335119551D6Abf68468A00F
 *      - rewardRate (e.g., 1e18 for 1 STRIVE/sec)
 *      - stakingOpenTime (epoch time for Jan 30, 2025, 21:20 UTC if that’s your goal)
 *  2. The contract will block staking if block.timestamp < stakingOpenTime.
 *  3. Even after staking opens, getReward() reverts until (stakingOpenTime + 8 hours).
 *  4. You can fund the contract with STRIVE by sending tokens directly to its address.
 */

// IMPORTANT: Specify a version of OpenZeppelin that uses ^0.8.0 <= 0.8.19



contract StriveStakingFinal is ReentrancyGuard {
    IERC20 public immutable striveToken;

    // Staking and reward tracking
    mapping(address => uint256) public stakedBalance;
    mapping(address => uint256) public rewards;
    uint256 public totalStaked;

    // Reward distribution variables
    uint256 public rewardRate;            // tokens distributed per second
    uint256 public lastUpdateTime;
    uint256 public rewardPerTokenStored;
    mapping(address => uint256) public userRewardPerTokenPaid;

    // Timing logic
    uint256 public stakingOpenTime;        // When users can start staking
    uint256 public rewardClaimTime;        // = stakingOpenTime + 8 hours

    // Constants
    uint256 public constant CLAIM_DELAY = 8 hours;

    // ------------------------
    // Constructor
    // ------------------------
    constructor(
        address _striveToken,
        uint256 _rewardRate,
        uint256 _stakingOpenTime
    ) {
        require(_striveToken != address(0), "Invalid STRIVE token address");
        require(_stakingOpenTime > block.timestamp, "stakingOpenTime must be in future");

        striveToken = IERC20(_striveToken);
        rewardRate = _rewardRate;
        stakingOpenTime = _stakingOpenTime;
        rewardClaimTime = _stakingOpenTime + CLAIM_DELAY;

        // Initialize
        lastUpdateTime = block.timestamp;
    }

    // ------------------------
    // Modifiers
    // ------------------------
    modifier updateReward(address account) {
        rewardPerTokenStored = rewardPerToken();
        lastUpdateTime = block.timestamp;

        if (account != address(0)) {
            rewards[account] = earned(account);
            userRewardPerTokenPaid[account] = rewardPerTokenStored;
        }
        _;
    }

    // ------------------------
    // View Functions
    // ------------------------

    function rewardPerToken() public view returns (uint256) {
        if (totalStaked == 0) {
            return rewardPerTokenStored;
        }
        uint256 timeDelta = block.timestamp - lastUpdateTime;
        uint256 totalReward = timeDelta * rewardRate;
        return rewardPerTokenStored + (totalReward * 1e18 / totalStaked);
    }

    function earned(address account) public view returns (uint256) {
        uint256 currentRPT = rewardPerToken();
        uint256 userRPTPaid = userRewardPerTokenPaid[account];
        uint256 userStaked = stakedBalance[account];

        uint256 newlyAccumulated = (userStaked * (currentRPT - userRPTPaid)) / 1e18;
        return rewards[account] + newlyAccumulated;
    }

    // ------------------------
    // User Functions
    // ------------------------

    // 1. Stake tokens (cannot stake before stakingOpenTime)
    function stake(uint256 amount) external nonReentrant updateReward(msg.sender) {
        require(block.timestamp >= stakingOpenTime, "Staking not open yet");
        require(amount > 0, "Cannot stake 0");

        // Transfer from user to contract
        striveToken.transferFrom(msg.sender, address(this), amount);

        totalStaked += amount;
        stakedBalance[msg.sender] += amount;
    }

    // 2. Withdraw staked tokens at any time
    function withdraw(uint256 amount) public nonReentrant updateReward(msg.sender) {
        require(amount > 0, "Cannot withdraw 0");
        uint256 userStaked = stakedBalance[msg.sender];
        require(userStaked >= amount, "Withdraw > stakedBalance");

        stakedBalance[msg.sender] = userStaked - amount;
        totalStaked -= amount;

        // Transfer back to user
        striveToken.transfer(msg.sender, amount);
    }

    // 3. Claim pending rewards (cannot claim before rewardClaimTime)
    function getReward() public nonReentrant updateReward(msg.sender) {
        require(block.timestamp >= rewardClaimTime, "Rewards not claimable yet");
        uint256 reward = rewards[msg.sender];
        if (reward > 0) {
            rewards[msg.sender] = 0;
            striveToken.transfer(msg.sender, reward);
        }
    }

    // 4. Exit completely (withdraw + claim)
    function exit() external {
        withdraw(stakedBalance[msg.sender]);
        getReward();
    }

    // ------------------------
    // Admin/Owner function (Optional)
    // ------------------------
    // You might want to restrict this with an Ownable pattern if you prefer.
    function setRewardRate(uint256 _newRate) external {
        // e.g. require(msg.sender == owner, "Not authorized");
        rewardRate = _newRate;
    }
}
